# ──────────────────────────────────────────────────────────────────────────────
# Runtime constants
# ──────────────────────────────────────────────────────────────────────────────

MAX_THREAD            = 5    # parallel tool calls in the NER agent
# DEFAULT_TOP_K: how many tools the FAISS tool-selector returns per question.
#
# Bumped from 10 → 15 because the partial-name probe showed that on the
# movie graph, top-10 systematically excluded Person tools when the
# question used relational verbs ("feature X in cast", "starring Y",
# "directed by Z"). The eight movie/film-series/award tools dominated the
# top half of the ranking and Person.name fell to ~#11, so the ReAct
# agent never even saw it and resorted to calling `get_movie_eid("Elijah
# Wood")` — a wrong-label tool with predictable empty results. 15 leaves
# slack for the agent to discover the right tool without inflating
# token usage materially.
DEFAULT_TOP_K         = 15   # FAISS tool-selection top-k
TOOL_TOP_K            = 10   # fulltext search top-k per tool call
STABILITY_K           = 3    # consecutive stable validation rounds before stopping
MAX_VALIDATION_ROUNDS = 20   # hard cap on validation rounds per property pair
SAMPLE_T              = 20   # sample size t per round (sample_property_values)
CAP_MULTIPLIER        = 1000    # scan cap = t * CAP_MULTIPLIER (cheap over-fetch for random sampling)


# ──────────────────────────────────────────────────────────────────────────────
# Value-linking configuration — four orthogonal axes
# ──────────────────────────────────────────────────────────────────────────────
# How (or whether) the grounding stage runs in front of the Cypher generator.
# Four independent choices, each env-overridable, resolved into a GroundingSpec:
#
#   VAL_LINK_MODE   no_val_link | fcav | graphrag | val_link
#                     no_val_link — feed only {schema}+{question} to the Cypher LLM
#                                   (lower bound: the Cypher LLM unaided).
#                     fcav        — standard retrieve-then-generate RAG baseline:
#                                   embed the question, retrieve candidate values
#                                   from a self-built value index, LLM generates
#                                   the entity JSON (see fcav.py; needs setup_fcav.py).
#                     graphrag    — Multi-Agent GraphRAG baseline: generate→execute→
#                                   LLM-evaluate; on a semantic miss feed feedback back
#                                   to the generator, on error/empty extract+verify the
#                                   Cypher's labels/values/rels and propose Levenshtein
#                                   replacements; iterate up to GRAPHRAG_MAX_ITER (see graphrag.py).
#                     val_link    — run the value-linking grounder (axes below apply).
#   AGENT_TYPE      react | plan_exec        (only when VAL_LINK_MODE=val_link)
#   RETRIEVAL_TYPE  fuzzy | hybrid           (only when VAL_LINK_MODE=val_link)
#                     drives both grounders: react via vector_config.TOOL_RETRIEVAL_MODE,
#                     plan_exec unions fuzzy+vector candidates per tool.
#   TOOL_TYPE       node | node_rel          (only when VAL_LINK_MODE=val_link)
#
# These four variables are the SOLE way to select the pipeline. Example —
# plan-and-execute, hybrid retrieval, node+relation tools:
#   VAL_LINK_MODE=val_link AGENT_TYPE=plan_exec RETRIEVAL_TYPE=hybrid TOOL_TYPE=node_rel python eval_run.py
# ──────────────────────────────────────────────────────────────────────────────
VAL_LINK_MODE:  str = os.getenv("VAL_LINK_MODE",  "no_val_link")  # no_val_link | fcav | graphrag | val_link
AGENT_TYPE:     str = os.getenv("AGENT_TYPE",     "plan_exec")    # react | plan_exec
RETRIEVAL_TYPE: str = os.getenv("RETRIEVAL_TYPE", "fuzzy")        # fuzzy | hybrid
TOOL_TYPE:      str = os.getenv("TOOL_TYPE",      "node_rel")     # node | node_rel

_VAL_LINK_MODES  = ("no_val_link", "fcav", "graphrag", "val_link")
_AGENT_TYPES     = ("react", "plan_exec")
_RETRIEVAL_TYPES = ("fuzzy", "hybrid")
_TOOL_TYPES      = ("node", "node_rel")


@dataclass(frozen=True)
class GroundingSpec:
    """Resolved value-linking configuration. ``agent`` / ``retrieval`` / ``tool``
    are ``None`` unless ``val_link == "val_link"``."""
    val_link:  str
    agent:     Optional[str] = None
    retrieval: Optional[str] = None
    tool:      Optional[str] = None

    @property
    def canonical(self) -> str:
        """Compact internal name the pipeline keys on: no_val_link→'no_ner',
        fcav→'fcav', graphrag→'graphrag', else
        '<agent>_<tool-suffix>[ _hybrid]' (tool 'node'→'node_only')."""
        if self.val_link == "no_val_link":
            return "no_ner"
        if self.val_link == "fcav":
            return "fcav"
        if self.val_link == "graphrag":
            return "graphrag"
        suffix = "node_only" if self.tool == "node" else "node_rel"
        name = f"{self.agent}_{suffix}"
        return name + "_hybrid" if self.retrieval == "hybrid" else name


def _spec_from_axes(val_link: str, agent: str, retrieval: str, tool: str) -> GroundingSpec:
    vl = (val_link or "no_val_link").strip().lower()
    if vl not in _VAL_LINK_MODES:
        raise ValueError(f"VAL_LINK_MODE must be one of {_VAL_LINK_MODES}, got {val_link!r}.")
    if vl != "val_link":
        return GroundingSpec(vl)
    ag, rt, tl = (agent or "").strip().lower(), (retrieval or "").strip().lower(), (tool or "").strip().lower()
    for label, val, allowed in (("AGENT_TYPE", ag, _AGENT_TYPES),
                                ("RETRIEVAL_TYPE", rt, _RETRIEVAL_TYPES),
                                ("TOOL_TYPE", tl, _TOOL_TYPES)):
        if val not in allowed:
            raise ValueError(
                f"{label} must be one of {allowed} when VAL_LINK_MODE='val_link', got {val!r}."
            )
    return GroundingSpec("val_link", ag, rt, tl)


def _spec_from_canonical(name: str) -> GroundingSpec:
    """Parse a canonical internal name (the :attr:`GroundingSpec.canonical` form)
    back into a spec. Used by internal callers that thread the flat string (e.g.
    the per-mode FAISS index selection); NOT a user-facing entry point."""
    n = (name or "").strip().lower()
    if n in ("", "no_ner"):
        return GroundingSpec("no_val_link")
    if n == "fcav":
        return GroundingSpec("fcav")
    if n == "graphrag":
        return GroundingSpec("graphrag")
    hybrid = n.endswith("_hybrid")
    core = n[: -len("_hybrid")] if hybrid else n
    for ag in ("plan_exec", "react"):
        if core.startswith(ag + "_"):
            suffix = core[len(ag) + 1:]
            tool = "node" if suffix == "node_only" else suffix   # flat 'node_only' → axis 'node'
            return _spec_from_axes("val_link", ag, "hybrid" if hybrid else "fuzzy", tool)
    raise ValueError(f"Unknown grounding mode {name!r}.")


def resolve_spec(mode=None) -> GroundingSpec:
    """Resolve the active :class:`GroundingSpec`.

    *mode* may be a :class:`GroundingSpec` (returned as-is), a canonical internal
    name string (parsed — used by internal callers), or ``None`` (read from the
    four axis variables — the user-facing entry point).
    """
    if isinstance(mode, GroundingSpec):
        return mode
    if mode:
        return _spec_from_canonical(mode)
    return _spec_from_axes(VAL_LINK_MODE, AGENT_TYPE, RETRIEVAL_TYPE, TOOL_TYPE)

# RAG baseline: the ReAct NER agent restricted to a SINGLE tool-call round and
# with the tool-result backfill DISABLED. It uses the same (node + relation)
# tool set as `full`, but the agent gets one think→act→observe cycle and must
# then answer — no iterative refinement, no safety net. This isolates "what one
# retrieval round of an LLM agent recovers" as a lower-effort baseline against
# the full agentic `full` / `node_only` modes (which loop + backfill).
# RAG_RECURSION_LIMIT caps the LangGraph supersteps: agent → tools → agent ≈ 3.
RAG_RECURSION_LIMIT = 1

# plan_exec baseline: a deterministic plan-and-execute grounder (no ReAct loop).
#   PLAN     — one LLM call decomposes the question into entity mentions, each
#              tagged node|relation + a short type descriptor.
#   EXECUTE  — per mention: route to the matching tool via the tool-VectorDB
#              (by descriptor), then search_tool(mention) for the top-K
#              canonical values (node mentions) / emit the relationship pattern
#              (relation mentions). No per-tool get_entity re-extraction.
#   GENERATE — the per-mention candidate lists are handed verbatim to the
#              Cypher LLM, which does the value-linking while writing Cypher.
# Contrasts with `full`: per-entity tool routing (no top-k tool crowding), no
# get_entity intermediate layer, and candidates (not a single forced pick) are
# given to the generator. Retrieval stays fuzzy (no value-embedding index).
PLAN_EXEC_TOOLS_PER_ENTITY = 2    # tools routed per extracted mention
PLAN_EXEC_VALUES_PER_TOOL  = 10   # top-K canonical values searched per tool (fuzzy modes)

# plan_exec_node_rel_hybrid: per tool, union fuzzy top-K with vector top-K
# candidates (fuzzy first, vector fills the tail). Tests whether in-graph
# embedding recall recovers the alias/abbrev cases fuzzy misses.
PLAN_EXEC_HYBRID_FUZZY_K  = 10    # fuzzy candidates per tool
PLAN_EXEC_HYBRID_VECTOR_K = 5     # embedding (vector-index) candidates per tool

# plan_exec corrective-retrieval escalation (orthogonal to fuzzy/hybrid):
# after the initial retrieval, an LLM judge checks whether the entity mention
# is actually grounded in the candidates retrieved so far. If not, retrieval is
# escalated with a diminishing budget — FIRST deeper into the already-used
# tool(s) (the canonical value may rank below the initial top-K), THEN to the
# next-ranked tools — re-judging after each step and stopping once grounded or
# the budget is spent. Only fires on a miss, so well-grounded entities pay just
# one judge call and no extra retrieval (avoids the candidate-noise penalty of
# blanket top-K increases).
PLAN_EXEC_ESCALATE        = os.getenv("PLAN_EXEC_ESCALATE", "1").lower() in ("1", "true", "yes")
PLAN_EXEC_MAX_ITER        = 3           # max escalation rounds per mention
PLAN_EXEC_ESCALATE_BUDGET = (5, 3, 1)   # values added per successive round (deepen step)
PLAN_EXEC_ROUTE_FETCH     = 6           # tools FAISS-routed per mention (initial + escalation pool)
# In escalation the LLM judge picks the next action from: done | value (deepen
# the used field) | a specific Label.property field to ADD (chosen from the menu
# of available node fields). 'value' deepens fuzzy in the fuzzy mode and BOTH
# fuzzy+vector in hybrid. A newly chosen field gets a full initial-style fetch.

# ──────────────────────────────────────────────────────────────────────────────
# Multi-Agent GraphRAG baseline  (VAL_LINK_MODE=graphrag — see graphrag.py)
# ──────────────────────────────────────────────────────────────────────────────
# A self-correcting generate→execute→evaluate loop (NO pre-grounding stage):
#
#   GENERATE  — the Cypher LLM writes a query from {schema}+{question} (round 1
#               has no entity hints; later rounds get the aggregated feedback).
#   EXECUTE   — run the query; classify (error | empty | rows).
#   EVALUATE  — an LLM judge labels the outcome:
#                 accept                        → format & return the answer.
#                 incorrect|illogical|incomplete→ hand the semantic/logical
#                                                 feedback straight to GENERATE.
#                 error|empty                   → STRUCTURAL repair: extract the
#                   query's node labels, property–value pairs and relationship
#                   patterns, verify each against the DB, retrieve normalized-
#                   Levenshtein candidate replacements for the invalid values,
#                   aggregate execution+semantic+validation feedback, regenerate.
#   …iterate up to GRAPHRAG_MAX_ITER rounds, then return the best attempt.
#
# Generator reuses CYPHER_LLM_CONFIG; evaluator/selector reuse NER_LLM_CONFIG.
# Selection is purely env-driven, like the other baselines:
#   VAL_LINK_MODE=graphrag python eval_run.py
GRAPHRAG_MAX_ITER       = 4     # generate→execute→correct rounds (paper = 4)
GRAPHRAG_CANDIDATE_K    = 10    # Levenshtein candidates retrieved per invalid value
GRAPHRAG_LEV_THRESHOLD  = 0.0   # min normalized-Levenshtein sim to keep a candidate (0 = keep all)
# Candidate replacements are ranked by normalized Levenshtein over the (label,
# property) value set — server-side via APOC (apoc.text.levenshteinSimilarity);
# if APOC is unavailable we scan distinct values in Python, capped at this many.
GRAPHRAG_SCAN_CAP       = 50000
GRAPHRAG_EMPTY_IS_WRONG = os.getenv("GRAPHRAG_EMPTY_IS_WRONG", "1").lower() in ("1", "true", "yes")
GRAPHRAG_LLM_EVALUATOR  = os.getenv("GRAPHRAG_LLM_EVALUATOR", "1").lower() in ("1", "true", "yes")

# ──────────────────────────────────────────────────────────────────────────────
# Cypher execution-error retry  (applies to the val_link Cypher stage only)
# ──────────────────────────────────────────────────────────────────────────────
# After value-linking finishes and the Cypher LLM has written a query, if that
# query FAILS TO EXECUTE (syntax/runtime error), feed the Neo4j error message
# back to the Cypher LLM and have it rewrite the query — up to
# CYPHER_RETRY_MAX_ROUNDS total attempts. This is error-driven only: an empty
# result is NOT a retry trigger (there is no error message to act on).
#
# Scope: only the value-linking pipeline (VAL_LINK_MODE=val_link, i.e. the
# ReAct / Plan&Exec grounders). The baselines (no_val_link, fcav) keep using
# GraphCypherQAChain unchanged; graphrag has its own loop.
# On a DB execution error the repair is a SINGLE error-message-informed CoT pass
# (reason about the error + required structure, then rewrite) — NOT N blind
# retries (blind re-rolls reproduce the same structural mistake; one CoT repair
# corrects more per round at far lower latency).
#   0 = use the legacy GraphCypherQAChain path (reproduce pre-retry ablations).
#   1 = single attempt, NO repair (transparent manual generate→execute path —
#       a clean A/B control).
#   2 = 1 generate + 1 CoT repair on error (default).
#   N = 1 generate + up to N-1 CoT repairs.
# NOTE: val_link with this knob uses a direct cypher_llm.invoke path (not
# GraphCypherQAChain). The recorded movie/flight ablations predate it and went
# through GraphCypherQAChain — re-measure the val_link rows for a clean compare.
CYPHER_RETRY_MAX_ROUNDS = int(os.getenv("CYPHER_RETRY_MAX_ROUNDS", "2"))
# Retry is error-driven only — an empty result does NOT trigger a rewrite. An
# empty result is not evidence of a wrong query (the answer may legitimately be
# empty), and on this benchmark the dominant failure is "wrong-but-non-empty"
# grounding, which execution feedback can't detect anyway. (Measured: empty-retry
# had 2/20 opportunities, fixed 0, and risks fabricating answers on zero-count
# questions.) The real lever there is semantic verification of the grounded value.

# ──────────────────────────────────────────────────────────────────────────────
# Plan&Exec value-snap  (post-generation grounding guard for the SELECTION error)
# ──────────────────────────────────────────────────────────────────────────────
# Targets the "retrieved-but-not-used" grounding failure: plan_exec DID retrieve
# the canonical value, but the Cypher LLM copied the question's perturbed surface
# form into the WHERE clause (e.g. WHERE p.name = "Tmo Hooper" while "Tom Hooper"
# sat in the candidate list). After generation, for each entity value the query
# uses:
#   • EXISTENCE GATE — if the value EXISTS in the DB, never touch it (so correct/
#     normal queries are structurally safe — they use real values).
#   • if it does NOT exist (the predicate provably matches 0 rows), one batched
#     LLM call picks the matching candidate from plan_exec's already-retrieved
#     candidates, or NONE. The pick is validated to be in the candidate list
#     (guards hallucination); NONE → no snap (recall misses are left for richer
#     retrieval, never fabricated).
# Only `=` / inline-map string literals are considered (not =~ / CONTAINS, which
# are intentional partials). plan_exec only; fires only on non-existent values,
# so the extra LLM call is rare. Set to 0 to disable.
PLAN_EXEC_VALUE_SNAP = os.getenv("PLAN_EXEC_VALUE_SNAP", "1").lower() in ("1", "true", "yes")

# Latency: skip the escalation loop for a mention that is ALREADY cleanly
# grounded — i.e. a retrieved candidate exact/substring-matches the mention
# (the free, no-LLM check from _judge_grounded's fast path). Only skips work
# that escalation would not have improved, so it's ~EA-neutral. Set 0 to ablate.
PLAN_EXEC_SKIP_GROUNDED = os.getenv("PLAN_EXEC_SKIP_GROUNDED", "1").lower() in ("1", "true", "yes")
# Latency: run the per-mention EXECUTE/escalation concurrently (mentions are
# independent — same calls, same results, just not serialized). Capped by
# MAX_THREAD. Set 0 to force serial.
PLAN_EXEC_PARALLEL_MENTIONS = os.getenv("PLAN_EXEC_PARALLEL_MENTIONS", "1").lower() in ("1", "true", "yes")

# ── Retrieval arm: normalized Levenshtein (for ablation) ─────────────────────
# Adds a third retrieval arm to plan_exec's INITIAL per-(label,property) lookup:
# a server-side APOC normalized-Levenshtein scan (apoc.text.levenshteinSimilarity),
# unioned in after fuzzy (and after vector when RETRIEVAL_TYPE=hybrid). Catches
# char-level perturbations fuzzy misses (abbrev codes FRA->France, typos). Handles
# scalar AND array (e.g. aliases) properties. Default OFF so the shipped behavior
# is unchanged; toggle per arm for ablation:
#   fuzzy             : RETRIEVAL_TYPE=fuzzy  PLAN_EXEC_LEVENSHTEIN=0
#   fuzzy+lev         : RETRIEVAL_TYPE=fuzzy  PLAN_EXEC_LEVENSHTEIN=1
#   fuzzy+vec         : RETRIEVAL_TYPE=hybrid PLAN_EXEC_LEVENSHTEIN=0
#   fuzzy+lev+vec     : RETRIEVAL_TYPE=hybrid PLAN_EXEC_LEVENSHTEIN=1
# NOTE: it is a full per-(label,prop) scan — cheap on small graphs (flight ~1.7k
# values), but O(N) per mention on large graphs (movie ~218k); gate before using
# it at movie scale.
PLAN_EXEC_LEVENSHTEIN   = os.getenv("PLAN_EXEC_LEVENSHTEIN", "0").lower() in ("1", "true", "yes")
PLAN_EXEC_LEVENSHTEIN_K = int(os.getenv("PLAN_EXEC_LEVENSHTEIN_K", "10"))

